// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes", wrapper.ListNotes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes", wrapper.CreateNote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/tags", wrapper.ListNoteTags)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/notes/tag-colors", wrapper.SetNoteTagColor)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/notes/{noteId}", wrapper.DeleteNote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/{noteId}", wrapper.GetNote)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/notes/{noteId}", wrapper.UpdateNote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/ai-settings", wrapper.GetNoteAiSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/notes/ai-settings", wrapper.PutNoteAiSettings)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes/ai/polish", wrapper.PolishNoteBody)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes/ai/title", wrapper.SuggestNoteTitle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes/ai/tags", wrapper.SuggestNoteTags)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/notes/{noteId}/suggested-tags", wrapper.DismissNoteSuggestedTags)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes/{noteId}/to-issue", wrapper.NoteToIssue)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes/{noteId}/to-reminder", wrapper.NoteToReminder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/{noteId}/attachments", wrapper.ListNoteAttachments)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notes/{noteId}/attachments", wrapper.UploadNoteAttachment)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/notes/attachments/{attachmentId}", wrapper.DeleteNoteAttachment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/attachments/{attachmentId}", wrapper.DownloadNoteAttachment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/counts", wrapper.GetNoteCounts)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/notes/{noteId}/share", wrapper.DeleteNoteShare)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notes/{noteId}/share", wrapper.GetNoteShare)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/notes/{noteId}/share", wrapper.PutNoteShare)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/public/notes/{token}", wrapper.GetPublicNote)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/public/notes/{token}/unlock", wrapper.UnlockPublicNote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/public/notes/{token}/files/{attachmentId}", wrapper.GetPublicNoteFile)
	})

	return r
}
